+"use client";
+
+import { useState } from "react";
+import { toast } from "sonner";
+import { Bomb, Eraser, Loader2 } from "lucide-react";
+import { AppShell, PageTitle } from "@/components/AppShell";
+import { useSwapDesk } from "@/store/swapdesk";
+import { ApiError, type FaultOut } from "@/lib/api";
+
+const opts = [
+  { k: "auto", l: "Autonomous resolution", d: "Resolve eligible tickets without human approval." },
+  { k: "idem", l: "Idempotency check before retry", d: "Query DB state after any timeout before re-calling a tool." },
+  { k: "verify", l: "Deterministic final verification", d: "Block resolution unless DB state matches planned reply." },
+  { k: "refund", l: "Allow refunds over $200", d: "Escalate high-value refunds to a human when off." },
+];
+
+const FAULT_STEPS = ["reserve", "return", "label", "finalize", "escalate", "cancel"] as const;
+const FAULT_POINTS = ["transient", "deplete_stock", "crash", "timeout", "release_fail"] as const;
+
+export default function SettingsPage() {
+  const { armFault, clearFaults } = useSwapDesk();
+  const [on, setOn] = useState<Record<string, boolean>>({ auto: true, idem: true, verify: true, refund: false });
+
+  const [caseId, setCaseId] = useState("");
+  const [runId, setRunId] = useState("RUN-1");
+  const [step, setStep] = useState<(typeof FAULT_STEPS)[number]>("reserve");
+  const [point, setPoint] = useState<(typeof FAULT_POINTS)[number]>("transient");
+  const [times, setTimes] = useState(1);
+  const [busy, setBusy] = useState(false);
+  const [armed, setArmed] = useState<FaultOut | null>(null);
+  const [faultError, setFaultError] = useState<string | null>(null);
+
+  const handleArm = async () => {
+    if (!caseId.trim()) {
+      setFaultError("Enter the case id the fault should target (e.g. CASE-xxxxxxxx).");
+      return;
+    }
+    setBusy(true);
+    setFaultError(null);
+    try {
+      const result = await armFault({ case_id: caseId.trim(), run_id: runId || "RUN-1", step, point, times });
+      setArmed(result);
+      toast(`Armed ${point} on ${step}`);
+    } catch (caught) {
+      setFaultError(caught instanceof ApiError || caught instanceof Error ? caught.message : "Could not arm the fault");
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  const handleClear = async () => {
+    setBusy(true);
+    setFaultError(null);
+    try {
+      await clearFaults();
+      setArmed(null);
+      toast("All demo faults disarmed");
+    } catch (caught) {
+      setFaultError(caught instanceof ApiError || caught instanceof Error ? caught.message : "Could not clear faults");
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  return (
+    <AppShell crumbs={[{ label: "SwapDesk", to: "/" }, { label: "Settings" }]} metrics={false}>
+      <PageTitle title="Settings" sub="Guardrails for swapdesk-agent v2.4.1" />
+      <div className="panel divide-y divide-hairline">
+        {opts.map((o) => (
+          <div key={o.k} className="flex items-center justify-between gap-4 p-5">
+            <div className="min-w-0">
+              <p className="text-sm font-semibold">{o.l}</p>
+              <p className="mt-0.5 text-xs text-muted-foreground">{o.d}</p>
+            </div>
+            <button
+              role="switch"
+              aria-checked={on[o.k]}
+              aria-label={o.l}
+              onClick={() => {
+                setOn({ ...on, [o.k]: !on[o.k] });
+                toast(`${o.l} ${on[o.k] ? "disabled" : "enabled"}`);
+              }}
+              className={`relative h-6 w-11 shrink-0 rounded-full border border-hairline transition-colors ${on[o.k] ? "bg-primary" : "bg-muted"}`}
+            >
+              <span
+                className={`absolute top-0.5 h-[18px] w-[18px] rounded-full bg-foreground transition-all ${on[o.k] ? "left-[22px]" : "left-0.5"}`}
+              />
+            </button>
+          </div>
+        ))}
+      </div>
+
+      <section className="mt-6">
+        <div className="mb-3 flex items-end justify-between">
+          <div>
+            <h2 className="text-lg font-semibold">Demo Fault Injection</h2>
+            <p className="text-sm text-muted-foreground">
+              Arm a one-shot failure on an operation key to exercise retry and recovery paths.
+            </p>
+          </div>
+          <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted-foreground">
+            POST · DELETE /v1/demo/faults
+          </span>
+        </div>
+
+        <div className="panel space-y-4 p-5">
+          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">
+            <label className="grid gap-1.5 text-xs font-medium text-muted-foreground lg:col-span-2">
+              Case id
+              <input
+                value={caseId}
+                onChange={(event) => setCaseId(event.target.value)}
+                placeholder="CASE-xxxxxxxx"
+                className="rounded-lg border border-hairline bg-background/60 px-3 py-2 font-mono text-sm text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-success/40"
+              />
+            </label>
+            <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
+              Run id
+              <input
+                value={runId}
+                onChange={(event) => setRunId(event.target.value)}
+                className="rounded-lg border border-hairline bg-background/60 px-3 py-2 font-mono text-sm text-foreground outline-none transition-colors focus:border-success/40"
+              />
+            </label>
+            <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
+              Step
+              <select
+                value={step}
+                onChange={(event) => setStep(event.target.value as (typeof FAULT_STEPS)[number])}
+                className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40"
+              >
+                {FAULT_STEPS.map((option) => (
+                  <option key={option} value={option}>
+                    {option}
+                  </option>
+                ))}
+              </select>
+            </label>
+            <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
+              Point
+              <select
+                value={point}
+                onChange={(event) => setPoint(event.target.value as (typeof FAULT_POINTS)[number])}
+                className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40"
+              >
+                {FAULT_POINTS.map((option) => (
+                  <option key={option} value={option}>
+                    {option}
+                  </option>
+                ))}
+              </select>
+            </label>
+          </div>
+
+          <div className="flex flex-wrap items-center gap-3">
+            <label className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
+              Times
+              <input
+                type="number"
+                min={1}
+                value={times}
+                onChange={(event) => setTimes(Math.max(1, Number(event.target.value) || 1))}
+                className="num w-20 rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40"
+              />
+            </label>
+            <button
+              type="button"
+              onClick={handleArm}
+              disabled={busy}
+              className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-70"
+            >
+              {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Bomb className="h-4 w-4" />}
+              Arm fault
+            </button>
+            <button
+              type="button"
+              onClick={handleClear}
+              disabled={busy}
+              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent/60 disabled:opacity-70"
+            >
+              <Eraser className="h-4 w-4" />
+              Clear all
+            </button>
+          </div>
+
+          {armed && (
+            <p className="rise rounded-lg border border-warning/25 bg-warning/[0.06] p-3 font-mono text-xs text-warning">
+              armed {armed.point} ×{armed.times} on {armed.op_key}
+            </p>
+          )}
+          {faultError && (
+            <p className="rounded-lg border border-danger/25 bg-danger/[0.06] p-3 text-sm text-danger">{faultError}</p>
+          )}
+        </div>
+      </section>
+    </AppShell>
+  );
+}

