import type { NextConfig } from "next";

const SWAPDESK_API_URL = (process.env.SWAPDESK_API_URL ?? "http://127.0.0.1:8000").replace(/\/$/, "");

const nextConfig: NextConfig = {
  /* config options here */
  experimental: {
    agentFeedback: true,
  },
  cacheComponents: true,
  partialPrefetching: true,
  async rewrites() {
    /* Proxy same-origin `/v1/*` calls to the SwapDesk FastAPI backend so the
       browser never hits a cross-origin request. Override the target with the
       SWAPDESK_API_URL environment variable. */
    return [{ source: "/v1/:path*", destination: `${SWAPDESK_API_URL}/v1/:path*` }];
  },
};

export default nextConfig;

