"use client";

import { useState } from "react";
import { RefreshCw, RotateCcw } from "lucide-react";
import { AppShell, PageTitle } from "@/components/AppShell";
import { useSwapDesk } from "@/store/swapdesk";
import type { FixtureItem, ReturnPolicy } from "@/lib/api";

function isEligible(item: FixtureItem, policy: ReturnPolicy): boolean {
  if (policy.final_sale_excluded && item.final_sale) return false;
  if (item.status !== policy.eligible_status) return false;
  if (!item.delivered_at) return false;
  const days = (Date.now() - Date.parse(item.delivered_at)) / 86_400_000;
  return days <= policy.window_days;
}

export default function InventoryPage() {
  const { inventory, fixtures, loadFixtures, resetMockData } = useSwapDesk();
  const [refreshing, setRefreshing] = useState(false);

  const refresh = async () => {
    setRefreshing(true);
    await loadFixtures();
    setRefreshing(false);
  };

  return (
    <AppShell crumbs={[{ label: "SwapDesk", to: "/" }, { label: "Inventory" }]}>
      <PageTitle
        title="Inventory"
        sub="Live fixture catalogue and return policy served by the SwapDesk API."
        right={
          <div className="flex shrink-0 items-center gap-2">
            <button
              type="button"
              onClick={refresh}
              disabled={refreshing}
              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-xs font-medium text-foreground transition-colors hover:bg-accent/60 disabled:opacity-60"
              title="Reload fixtures from GET /v1/fixtures"
            >
              <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? "animate-spin" : ""}`} />
              Refresh
            </button>
            <button
              type="button"
              onClick={resetMockData}
              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-xs font-medium text-foreground transition-colors hover:bg-accent/60"
              title="Clear the ticket queue and restore local demo defaults"
            >
              <RotateCcw className="h-3.5 w-3.5" />
              Reset Mock Data
            </button>
          </div>
        }
      />

      {fixtures ? (
        <>
          <div className="panel mb-4 flex flex-wrap items-center gap-x-6 gap-y-2 p-4 text-xs text-muted-foreground">
            <span className="font-mono uppercase tracking-[0.18em] text-muted-foreground/80">Return policy</span>
            <span>
              Window <span className="num text-foreground">{fixtures.policy.window_days}d</span>
            </span>
            <span>
              Eligible status <span className="font-mono text-foreground">{fixtures.policy.eligible_status}</span>
            </span>
            <span>
              Final sale excluded{" "}
              <span className="font-mono text-foreground">{fixtures.policy.final_sale_excluded ? "yes" : "no"}</span>
            </span>
          </div>

          <div className="panel overflow-x-auto">
            <table className="w-full min-w-[720px] text-sm">
              <thead className="text-left text-xs text-muted-foreground">
                <tr className="border-b border-hairline">
                  {["Item", "SKU", "Size", "Order", "Status", "Delivered", "Final Sale", "Eligible"].map((h) => (
                    <th key={h} className="px-5 py-3 font-medium">
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-hairline">
                {fixtures.orders.flatMap((order) =>
                  order.items.map((item) => {
                    const eligible = isEligible(item, fixtures.policy);
                    return (
                      <tr key={item.id} className="hover:bg-accent/30">
                        <td className="px-5 py-3 font-mono text-xs">{item.id}</td>
                        <td className="px-5 py-3 font-mono text-xs">{item.sku}</td>
                        <td className="num px-5 py-3">{item.size}</td>
                        <td className="px-5 py-3 font-mono text-xs text-muted-foreground">{order.id}</td>
                        <td className="px-5 py-3">{item.status}</td>
                        <td className="px-5 py-3 text-muted-foreground">{item.delivered_at ?? "—"}</td>
                        <td className="px-5 py-3">
                          {item.final_sale ? <span className="text-warning">Yes</span> : <span className="text-muted-foreground">No</span>}
                        </td>
                        <td className="px-5 py-3">
                          <span className={eligible ? "font-medium text-success" : "text-danger"}>
                            {eligible ? "Eligible" : "Ineligible"}
                          </span>
                        </td>
                      </tr>
                    );
                  }),
                )}
              </tbody>
            </table>
          </div>
        </>
      ) : (
        <div className="panel overflow-x-auto">
          <div className="border-b border-hairline px-5 py-3 text-xs text-muted-foreground">
            Backend offline — showing local demo stock.
          </div>
          <table className="w-full min-w-[640px] text-sm">
            <thead className="text-left text-xs text-muted-foreground">
              <tr className="border-b border-hairline">
                {["SKU", "Product", "Size", "Available", "Reserved", "Warehouse"].map((h) => (
                  <th key={h} className="px-5 py-3 font-medium">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-hairline">
              {inventory.map((i) => (
                <tr key={i.sku} className="hover:bg-accent/30">
                  <td className="px-5 py-3 font-mono text-xs">{i.sku}</td>
                  <td className="px-5 py-3">{i.name}</td>
                  <td className="num px-5 py-3">{i.size}</td>
                  <td className={`num px-5 py-3 ${i.stock === 0 ? "text-danger" : ""}`}>{i.stock}</td>
                  <td className={`num px-5 py-3 ${i.res ? "text-success" : "text-muted-foreground"}`}>{i.res}</td>
                  <td className="px-5 py-3 font-mono text-xs text-muted-foreground">{i.wh}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </AppShell>
  );
}

"use client";

import { useEffect, useMemo, useState, type FormEvent } from "react";
import Link from "next/link";
import { ArrowRight, CheckCircle2, Loader2, Send, ShieldAlert } from "lucide-react";
import { useSwapDesk } from "@/store/swapdesk";
import { ApiError, type Outcome } from "@/lib/api";

const DEFAULT_COMPLAINT = "My Jordan 4s arrived but are too tight. I need to exchange for a size 43.";

const OUTCOME_LABEL: Record<Outcome, string> = {
  arranged: "Exchange arranged",
  clarification: "Clarification required",
  denial: "Policy denial",
  escalation: "Escalated to human",
};

export function CustomerSimulationWidget() {
  const { fixtures, loadFixtures, submitTicket, submitAgentTicket } = useSwapDesk();
  const [complaint, setComplaint] = useState("");
  const [mode, setMode] = useState<"deterministic" | "agent">("deterministic");
  const [orderId, setOrderId] = useState("");
  const [itemId, setItemId] = useState("");
  const [size, setSize] = useState("");
  const [status, setStatus] = useState<"idle" | "routing" | "done">("idle");
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<{ caseId: string; outcome: Outcome; reply: string } | null>(null);

  useEffect(() => {
    if (!fixtures) void loadFixtures();
  }, [fixtures, loadFixtures]);

  const orders = fixtures?.orders ?? [];
  const selectedOrder = useMemo(() => orders.find((order) => order.id === orderId), [orders, orderId]);
  const items = selectedOrder?.items ?? [];

  useEffect(() => {
    if (items.length > 0 && !items.some((item) => item.id === itemId)) {
      setItemId(items[0].id);
      setSize(items[0].size);
    }
    if (items.length === 0) {
      setItemId("");
    }
  }, [items, itemId]);

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (status === "routing") return;

    setStatus("routing");
    setError(null);
    setResult(null);
    try {
      if (mode === "agent") {
        const ticket = await submitAgentTicket({
          message: complaint.trim() || DEFAULT_COMPLAINT,
          order_id: orderId || null,
          order_item_id: itemId || null,
          size: size || null,
        });
        setResult({ caseId: ticket.id, outcome: ticket.outcome!, reply: ticket.reply ?? "" });
      } else {
        if (!orderId || !itemId) {
          throw new Error("Select an order and item for a deterministic run.");
        }
        const ticket = await submitTicket({
          order_id: orderId,
          order_item_id: itemId,
          size,
          message: complaint.trim(),
        });
        setResult({ caseId: ticket.id, outcome: ticket.outcome!, reply: ticket.reply ?? "" });
      }
      setStatus("done");
    } catch (caught) {
      const message =
        caught instanceof ApiError || caught instanceof Error
          ? caught.message
          : "The request failed. Is the backend running?";
      setError(message);
      setStatus("idle");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="panel space-y-5 p-5 sm:p-6">
      <div className="grid gap-2">
        <span className="block text-sm font-semibold">Handling mode</span>
        <div className="inline-flex rounded-lg border border-hairline bg-background/60 p-0.5 text-xs">
          {(["deterministic", "agent"] as const).map((option) => (
            <button
              key={option}
              type="button"
              onClick={() => setMode(option)}
              disabled={status === "routing"}
              className={`rounded-md px-3 py-1.5 font-medium transition-colors disabled:opacity-60 ${
                mode === option ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {option === "deterministic" ? "Deterministic (POST /v1/tickets)" : "Agent (POST /v1/agent/tickets)"}
            </button>
          ))}
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-3">
        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Order
          <select
            value={orderId}
            onChange={(event) => setOrderId(event.target.value)}
            disabled={status === "routing" || mode === "agent"}
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40 disabled:opacity-60"
          >
            <option value="">Select order…</option>
            {orders.map((order) => (
              <option key={order.id} value={order.id}>
                {order.id} · {order.customer_ref}
              </option>
            ))}
          </select>
        </label>

        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Item
          <select
            value={itemId}
            onChange={(event) => {
              const next = items.find((item) => item.id === event.target.value);
              setItemId(event.target.value);
              if (next) setSize(next.size);
            }}
            disabled={status === "routing" || mode === "agent" || items.length === 0}
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40 disabled:opacity-60"
          >
            <option value="">Select item…</option>
            {items.map((item) => (
              <option key={item.id} value={item.id}>
                {item.id} · {item.sku} · {item.size}
              </option>
            ))}
          </select>
        </label>

        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Requested size
          <input
            value={size}
            onChange={(event) => setSize(event.target.value)}
            disabled={status === "routing"}
            placeholder="43"
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-success/40 disabled:opacity-60"
          />
        </label>
      </div>

      <div className="space-y-2">
        <label htmlFor="complaint" className="block text-sm font-semibold">
          Customer complaint
        </label>
        <textarea
          id="complaint"
          name="complaint"
          rows={5}
          value={complaint}
          onChange={(event) => setComplaint(event.target.value)}
          placeholder={DEFAULT_COMPLAINT}
          disabled={status === "routing"}
          className="w-full resize-none rounded-xl border border-hairline bg-background/60 p-4 text-sm leading-relaxed text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-success/40 disabled:opacity-60"
        />
      </div>

      <button
        type="submit"
        disabled={status === "routing"}
        className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-70 sm:w-auto"
      >
        {status === "routing" ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            {mode === "agent" ? "Routing to agent…" : "Running exchange…"}
          </>
        ) : (
          <>
            <Send className="h-4 w-4" />
            Submit to SwapDesk
          </>
        )}
      </button>

      {error && (
        <div className="rise flex items-start gap-3 rounded-xl border border-danger/25 bg-danger/[0.06] p-4">
          <ShieldAlert className="mt-0.5 h-4 w-4 shrink-0 text-danger" />
          <p className="text-sm text-danger">{error}</p>
        </div>
      )}

      {status === "done" && result && (
        <div className="rise flex flex-col gap-3 rounded-xl border border-success/20 bg-success/[0.06] p-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-start gap-3">
            <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-success" />
            <div>
              <p className="text-sm font-semibold text-foreground">
                {result.caseId} · {OUTCOME_LABEL[result.outcome]}
              </p>
              <p className="text-xs text-muted-foreground">{result.reply}</p>
            </div>
          </div>
          <Link
            href={`/ticket/${result.caseId}`}
            className="inline-flex shrink-0 items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-xs font-medium text-foreground transition-colors hover:bg-accent/60"
          >
            View case
            <ArrowRight className="h-3.5 w-3.5" />
          </Link>
        </div>
      )}
    </form>
  );
}

"use client";

import { Suspense, useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { ArrowLeft, Clock3, Loader2, RefreshCw, Send, ShieldAlert, ShieldCheck } from "lucide-react";
import { AppShell } from "@/components/AppShell";
import { useSwapDesk } from "@/store/swapdesk";
import { ApiError, type CaseStatusOut, type Outcome, type TimelineEvent } from "@/lib/api";

const OUTCOME_META: Record<Outcome, { label: string; tone: "success" | "warning" | "danger" | "primary" }> = {
  arranged: { label: "Exchange arranged", tone: "success" },
  clarification: { label: "Clarification required", tone: "primary" },
  denial: { label: "Policy denial", tone: "warning" },
  escalation: { label: "Escalated to human", tone: "danger" },
};

function humanize(value: string | null): string {
  if (!value) return "Event";
  return value.replace(/_/g, " ").replace(/\b\w/g, (char) => char.toUpperCase());
}

function eventDetail(event: TimelineEvent): string {
  const parts = [event.event.replace(/_/g, " ")];
  if (event.status) parts.push(`status=${event.status}`);
  const result = event.result ?? {};
  for (const key of ["exchange_id", "return_id", "label_id", "tracking_ref"]) {
    const value = result[key];
    if (typeof value === "string") parts.push(`${key}=${value}`);
  }
  if (result.duplicate === true) parts.push("duplicate reused");
  return parts.join(" · ");
}

function TicketDetailContent() {
  const params = useParams<{ id: string }>();
  const id = params?.id;
  const { getTicket, getCase, getTimeline, continueCase } = useSwapDesk();
  const localTicket = id ? getTicket(id) : undefined;

  const [status, setStatus] = useState<CaseStatusOut | null>(null);
  const [events, setEvents] = useState<TimelineEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [consentSize, setConsentSize] = useState("");
  const [continuing, setContinuing] = useState(false);
  const [continueError, setContinueError] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    setLoadError(null);
    const [nextStatus, nextEvents] = await Promise.all([getCase(id), getTimeline(id)]);
    setStatus(nextStatus);
    setEvents(nextEvents);
    if (!nextStatus) {
      setLoadError("No backend case with this id. It may be a local demo ticket.");
    }
    setLoading(false);
  }, [id, getCase, getTimeline]);

  useEffect(() => {
    void load();
  }, [load]);

  const handleContinue = async () => {
    if (!id || continuing) return;
    setContinuing(true);
    setContinueError(null);
    try {
      await continueCase(id, { consent_size: consentSize || null, message: "" });
      setConsentSize("");
      await load();
    } catch (caught) {
      setContinueError(caught instanceof ApiError || caught instanceof Error ? caught.message : "Continue failed");
    } finally {
      setContinuing(false);
    }
  };

  const outcome = status?.outcome;
  const meta = outcome ? OUTCOME_META[outcome] : null;
  const canContinue = outcome === "clarification" || outcome === "escalation";

  return (
    <AppShell crumbs={[{ label: "SwapDesk", to: "/" }, { label: "Mission Control", to: "/" }, { label: id ?? "Unknown" }]}>
      <div className="mx-auto w-full max-w-6xl space-y-6">
        <header className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <h1 className="text-2xl font-semibold">
              {status?.reply ?? localTicket?.message ?? "Case not found"}
            </h1>
            <p className="mt-1 text-sm text-muted-foreground">
              {id} {meta ? `· ${meta.label}` : status ? "" : "· no matching case"}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => void load()}
              disabled={loading}
              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-sm text-foreground transition-colors hover:bg-accent/60 disabled:opacity-60"
            >
              <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} /> Refresh
            </button>
            <Link
              href="/"
              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-sm text-foreground transition-colors hover:bg-accent/60"
            >
              <ArrowLeft className="h-4 w-4" /> Back
            </Link>
          </div>
        </header>

        <section className="grid gap-3 sm:grid-cols-3">
          <div className="panel flex items-center gap-3 p-4">
            <span
              className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl border ${
                meta?.tone === "success"
                  ? "border-success/15 bg-success/[0.07] text-success"
                  : meta?.tone === "warning"
                    ? "border-warning/15 bg-warning/[0.07] text-warning"
                    : meta?.tone === "danger"
                      ? "border-danger/15 bg-danger/[0.07] text-danger"
                      : "border-primary/15 bg-primary/[0.07] text-primary"
              }`}
            >
              {meta?.tone === "success" ? <ShieldCheck className="h-4 w-4" /> : meta?.tone === "primary" ? <Clock3 className="h-4 w-4" /> : <ShieldAlert className="h-4 w-4" />}
            </span>
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">Outcome</p>
              <p className="truncate text-sm font-semibold">{meta?.label ?? localTicket?.statusLabel ?? "Unknown"}</p>
            </div>
          </div>
          <div className="panel flex items-center gap-3 p-4">
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">Exchange</p>
              <p className="truncate font-mono text-sm">{status?.exchange_id ?? localTicket?.exchangeId ?? "—"}</p>
            </div>
          </div>
          <div className="panel flex items-center gap-3 p-4">
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">Runs</p>
              <p className="truncate font-mono text-sm">{status?.runs?.join(", ") || localTicket?.runId || "—"}</p>
            </div>
          </div>
        </section>

        <section>
          <div className="mb-3 flex items-center justify-between">
            <h2 className="text-lg font-semibold">Execution Timeline</h2>
            <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted-foreground">
              GET /v1/cases/{id}/timeline
            </span>
          </div>
          <div className="panel overflow-x-auto p-4 font-mono text-xs leading-7 sm:p-6 sm:text-[13px]">
            {loading && events.length === 0 ? (
              <p className="flex items-center gap-2 text-muted-foreground">
                <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading timeline…
              </p>
            ) : events.length === 0 ? (
              <p className="text-muted-foreground">{loadError ?? "No timeline events recorded for this case."}</p>
            ) : (
              events.map((event, index) => (
                <div key={`${event.op_key}-${index}`} className="flex gap-4 whitespace-nowrap">
                  <span className="text-muted-foreground/60">
                    {new Date(event.created_at).toLocaleTimeString()}
                  </span>
                  <span className={`w-52 shrink-0 ${event.status === "committed" ? "text-success" : "text-warning"}`}>
                    {humanize(event.op_type)}
                  </span>
                  <span className="text-foreground/80">{eventDetail(event)}</span>
                </div>
              ))
            )}
          </div>
        </section>

        {canContinue && (
          <section className="panel space-y-3 p-5">
            <h2 className="text-lg font-semibold">Continue case</h2>
            <p className="text-sm text-muted-foreground">
              Provide the customer&apos;s consent (for example a substitute size) and run the case again.
            </p>
            <div className="flex flex-wrap items-center gap-2">
              <input
                value={consentSize}
                onChange={(event) => setConsentSize(event.target.value)}
                placeholder="Consent size (e.g. 44)"
                className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-success/40"
              />
              <button
                type="button"
                onClick={handleContinue}
                disabled={continuing}
                className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-70"
              >
                {continuing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                Continue
              </button>
            </div>
            {continueError && (
              <p className="flex items-center gap-2 text-sm text-danger">
                <ShieldAlert className="h-4 w-4" /> {continueError}
              </p>
            )}
          </section>
        )}

        {!loading && !status && (
          <div className="panel p-6">
            <p className="text-sm text-muted-foreground">
              This case is not in the backend. Local demo tickets (like TCK-9042) have no server record — simulate an
              exchange to create a real case.
            </p>
          </div>
        )}
      </div>
    </AppShell>
  );
}

function TicketDetailFallback() {
  return (
    <div className="mx-auto w-full max-w-6xl px-4 py-6 sm:px-6 lg:px-8">
      <div className="panel flex items-center gap-3 p-6">
        <span className="h-2 w-2 rounded-full bg-success pulse-dot" />
        <p className="text-sm text-muted-foreground">Loading ticket…</p>
      </div>
    </div>
  );
}

export default function TicketDetailPage() {
  return (
    <Suspense fallback={<TicketDetailFallback />}>
      <TicketDetailContent />
    </Suspense>
  );
}

