+/**
+ * Typed client for the SwapDesk local mock API.
+ *
+ * The browser calls same-origin `/v1/...` paths; `next.config.ts` proxies
+ * those to the FastAPI backend (default `http://127.0.0.1:8000`). Set
+ * `NEXT_PUBLIC_SWAPDESK_API_URL` to call a remote origin directly instead
+ * (that origin must then allow CORS).
+ */
+
+const API_ORIGIN = (process.env.NEXT_PUBLIC_SWAPDESK_API_URL ?? "").replace(/\/$/, "");
+
+export const API_BASE = `${API_ORIGIN}/v1`;
+
+export class ApiError extends Error {
+  status: number;
+  detail: unknown;
+
+  constructor(status: number, message: string, detail?: unknown) {
+    super(message);
+    this.name = "ApiError";
+    this.status = status;
+    this.detail = detail;
+  }
+}
+
+async function request<T>(path: string, init?: RequestInit): Promise<T> {
+  let response: Response;
+  try {
+    response = await fetch(`${API_BASE}${path}`, {
+      ...init,
+      headers: {
+        ...(init?.body ? { "Content-Type": "application/json" } : {}),
+        ...init?.headers,
+      },
+      cache: "no-store",
+    });
+  } catch {
+    throw new ApiError(0, "Cannot reach the SwapDesk API. Is the backend running?");
+  }
+
+  const text = await response.text();
+  const payload = text ? safeJson(text) : null;
+
+  if (!response.ok) {
+    const detail =
+      payload && typeof payload === "object" && "detail" in payload
+        ? (payload as { detail: unknown }).detail
+        : payload;
+    const message =
+      typeof detail === "string" ? detail : `Request failed with status ${response.status}`;
+    throw new ApiError(response.status, message, payload);
+  }
+
+  return payload as T;
+}
+
+function safeJson(text: string): unknown {
+  try {
+    return JSON.parse(text);
+  } catch {
+    return text;
+  }
+}
+
+/* ------------------------------------------------------------------ types */
+
+export type Outcome = "arranged" | "clarification" | "denial" | "escalation";
+
+export type HealthOut = {
+  ok: boolean;
+  service: string;
+};
+
+export type ReturnPolicy = {
+  window_days: number;
+  eligible_status: string;
+  final_sale_excluded: boolean;
+};
+
+export type FixtureItem = {
+  id: string;
+  sku: string;
+  size: string;
+  qty: number;
+  status: string;
+  delivered_at: string | null;
+  final_sale: boolean;
+};
+
+export type FixtureOrder = {
+  id: string;
+  customer_ref: string;
+  items: FixtureItem[];
+};
+
+export type FixturesOut = {
+  orders: FixtureOrder[];
+  policy: ReturnPolicy;
+};
+
+export type TicketIn = {
+  order_id: string;
+  order_item_id: string;
+  size?: string;
