+  size: string;
+  qty: number;
+  status: string;
+  delivered_at: string | null;
+  final_sale: boolean;
+};
+
+export type FixtureOrder = {
+  id: string;
+  customer_ref: string;
+  items: FixtureItem[];
+};
+
+export type FixturesOut = {
+  orders: FixtureOrder[];
+  policy: ReturnPolicy;
+};
+
+export type AgentTicketIn = {
+  message: string;
+  order_id?: string | null;
+  order_item_id?: string | null;
+  size?: string | null;
+  qty?: number;
+  consent_size?: string | null;
