+
+export type AgentContinueIn = {
+  message?: string;
+  consent_size?: string | null;
+  order_id?: string | null;
+  order_item_id?: string | null;
+  size?: string | null;
+  qty?: number;
+};
+
+/** `POST /v1/agent/cases/{id}/continue`. `continued=false` for terminal cases. */
+export type AgentContinueOut = {
+  case_id: string;
+  run_id: string | null;
+  execution_status: ExecutionStatus;
+  continued: boolean;
+  outcome: Outcome | null;
+  reply: string | null;
+  exchange_id: string | null;
+};
+
+/* -------------------------------------------------------------- endpoints */
+
+/** GET /v1/health — liveness probe. */
+export function getHealth(): Promise<HealthOut> {
+  return request<HealthOut>("/health");
+}
+
+/** GET /v1/fixtures — synthetic orders/items and the return policy. */
+export function getFixtures(): Promise<FixturesOut> {
+  return request<FixturesOut>("/fixtures");
+}
+
+/**
+ * POST /v1/agent/tickets — accept an agent ticket for asynchronous
+ * execution. Returns 202 with the new case id; poll `getAgentCase` for
+ * progress and outcome.
+ */
+export function submitAgentTicket(input: AgentTicketIn): Promise<AgentAccepted> {
+  return request<AgentAccepted>("/agent/tickets", {
+    method: "POST",
+    body: JSON.stringify(input),
+  });
+}
+
+/** GET /v1/agent/cases/{id} — execution status, outcome, and clarification. */
+export function getAgentCase(caseId: string): Promise<AgentStatusOut> {
+  return request<AgentStatusOut>(`/agent/cases/${encodeURIComponent(caseId)}`);
+}
+
+/** GET /v1/agent/cases/{id}/timeline — sanitized events tagged with run ids. */
+export function getAgentCaseTimeline(caseId: string): Promise<TimelineEvent[]> {
+  return request<TimelineEvent[]>(`/agent/cases/${encodeURIComponent(caseId)}/timeline`);
+}
+
+/**
+ * POST /v1/agent/cases/{id}/continue — continue a case through the same
+ * agent path. Returns 202 when a fresh run was queued (`continued=true`);
+ * terminal cases echo their saved result with `continued=false`.
+ */
+export function continueAgentCase(
+  caseId: string,
+  input: AgentContinueIn,
+): Promise<AgentContinueOut> {
+  return request<AgentContinueOut>(`/agent/cases/${encodeURIComponent(caseId)}/continue`, {
+    method: "POST",
+    body: JSON.stringify(input),
+  });
+}

