+      const accepted = await apiSubmitAgentTicket(input);
+      const ticket: Ticket = {
+        id: accepted.case_id,
+        message: input.message,
+        status: "processing",
+        statusLabel: accepted.execution_status === "queued" ? "Queued" : "Agent Processing",
+        actions: ["INTAKE", accepted.run_id.toUpperCase()],
+        time: "Just now",
+        sku: input.order_item_id ?? "—",
+        live: true,
+        executionStatus: accepted.execution_status,
+        runId: accepted.run_id,
+        duplicate: accepted.duplicate,
+      };
+      rememberTicket(ticket);
+      setHealth("online");
+      setApiError(null);
+      watchCase(accepted.case_id);
+      return ticket;
+    },
+    [rememberTicket, watchCase],
+  );
+
+  const loadCase = useCallback(
+    async (id: string) => {
+      try {
+        const status = await apiGetAgentCase(id);
