+                  ...ticket,
+                  status: "processing",
+                  statusLabel: "Queued",
+                  executionStatus: "queued",
+                  outcome: undefined,
+                  reply: undefined,
+                  clarification: null,
+                  error: null,
+                  runId: result.run_id ?? ticket.runId,
+                }
+              : ticket,
+          ),
+        );
+        watchCase(id);
+      } else {
+        await loadCase(id);
+      }
