   const completionRate =
     totalTickets > 0 ? `${Math.round((resolvedTickets / totalTickets) * 100)}%` : "N/A";
 
   const handleSimulateTicket = () => {
     router.push("/simulate");
   };
 
   return (
     <div className="flex min-h-screen w-full">
