+                    : health === "offline"
+                      ? "border-danger/20 bg-danger/[0.06] text-danger"
+                      : "border-hairline bg-card/60 text-muted-foreground"
+                }`}
+                title={apiOnline ? "Connected to the SwapDesk API" : health === "offline" ? "Backend unreachable — showing local demo data" : "Checking API connection"}
+              >
+                <span className={`h-1.5 w-1.5 rounded-full ${apiOnline ? "bg-success pulse-dot" : health === "offline" ? "bg-danger" : "bg-muted-foreground"}`} />
+                {apiOnline ? "API Online" : health === "offline" ? "API Offline" : "Connecting…"}
+              </span>
               <button
                 type="button"
                 onClick={handleSimulateTicket}
                 className="inline-flex shrink-0 items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-xs font-medium text-foreground transition-colors hover:bg-accent/60"
