--- frontend/src/lib/api.ts	
+++ frontend/src/lib/api.ts	
@@ -0,0 +1,334 @@
+/**
+ * Typed client for the SwapDesk backend API.
+ *
+ * The browser calls same-origin `/v1/...` paths; `next.config.ts` proxies
+ * those to the deployed FastAPI backend
+ * (`https://swapdesk-7yvl.onrender.com`, overridable with `SWAPDESK_API_URL`).
+ * Set `NEXT_PUBLIC_SWAPDESK_API_URL` to call a remote origin directly instead
+ * (that origin must then allow CORS).
+ *
+ * Only the agent contract in `docs/API_CONTRACT.md` is used here. The
+ * legacy `/v1/tickets`, `/v1/cases/*`, and `/v1/demo/faults` routes are
+ * deliberately excluded: agent tickets are accepted asynchronously (202)
+ * and their progress is read by polling the status/timeline routes.
+ */
+
+const API_ORIGIN = (process.env.NEXT_PUBLIC_SWAPDESK_API_URL ?? "").replace(/\/$/, "");
+
+export const API_BASE = `${API_ORIGIN}/v1`;
+
+export class ApiError extends Error {
+  status: number;
+  detail: unknown;
+
+  constructor(status: number, message: string, detail?: unknown) {
+    super(message);
+    this.name = "ApiError";
+    this.status = status;
+    this.detail = detail;
+  }
+}
+
+async function request<T>(path: string, init?: RequestInit): Promise<T> {
+  let response: Response;
+  try {
+    response = await fetch(`${API_BASE}${path}`, {
+      ...init,
+      headers: {
+        ...(init?.body ? { "Content-Type": "application/json" } : {}),
+        ...init?.headers,
+      },
+      cache: "no-store",
+    });
+  } catch {
+    throw new ApiError(0, "Cannot reach the SwapDesk API. Is the backend running?");
+  }
+
+  const text = await response.text();
+  const payload = text ? safeJson(text) : null;
+
+  if (!response.ok) {
+    const detail =
+      payload && typeof payload === "object" && "detail" in payload
+        ? (payload as { detail: unknown }).detail
+        : payload;
+    const message =
+      typeof detail === "string" ? detail : `Request failed with status ${response.status}`;
+    throw new ApiError(response.status, message, payload);
+  }
+
+  return payload as T;
+}
+
+function safeJson(text: string): unknown {
+  try {
+    return JSON.parse(text);
+  } catch {
+    return text;
+  }
+}
+
+/* ------------------------------------------------------------------ types */
+
+/** Business outcome once a run reaches a terminal state. */
+export type Outcome = "arranged" | "clarification" | "denial" | "escalation";
+
+/** Rolled-up execution state of a case across its runs. */
+export type ExecutionStatus =
+  | "queued"
+  | "running"
+  | "waiting_input"
+  | "completed"
+  | "failed";
+
+export type HealthOut = {
+  ok: boolean;
+  service: string;
+};
+
+/** `GET /v1/ready` — deployment readiness derived from queue state. */
+export type ReadyOut = {
+  ok: boolean;
+  service: string;
+  queued_depth: number;
+  oldest_queued_age_s: number | null;
+  last_terminal_at: string | null;
+  note: string;
+};
+
+export type ReturnPolicy = {
+  window_days: number;
+  eligible_status: string;
+  final_sale_excluded: boolean;
+};
+
+export type FixtureItem = {
+  id: string;
+  sku: string;
+  size: string;
+  qty: number;
+  status: string;
+  delivered_at: string | null;
+  final_sale: boolean;
+};
+
+export type FixtureOrder = {
+  id: string;
+  customer_ref: string;
+  items: FixtureItem[];
+};
+
+export type FixturesOut = {
+  orders: FixtureOrder[];
+  policy: ReturnPolicy;
+};
+
+/** Row from `GET /v1/inventory` — real stock keyed by SKU and size. */
+export type InventoryRow = {
+  sku: string;
+  size: string;
+  on_hand: number;
+  held: number;
+  available: number;
+};
+
+export type InventoryOut = {
+  items: InventoryRow[];
+  limit: number;
+  offset: number;
+  total: number;
+  read_at: string;
+};
+
+export type InventoryQuery = {
+  sku?: string;
+  size?: string;
+  limit?: number;
+  offset?: number;
+};
+
+export type AgentTicketIn = {
+  message: string;
+  order_id?: string | null;
+  order_item_id?: string | null;
+  size?: string | null;
+  qty?: number;
+  consent_size?: string | null;
+  case_id?: string | null;
+  idempotency_key?: string | null;
+  resume?: boolean;
+};
+
+/** 202 accepted body from `POST /v1/agent/tickets`. */
+export type AgentAccepted = {
+  case_id: string;
+  run_id: string;
+  execution_status: ExecutionStatus;
+  status_url: string;
+  duplicate: boolean;
+};
+
+/** `GET /v1/agent/cases/{id}` — responsive, read-only case status. */
+export type AgentStatusOut = {
+  case_id: string;
+  execution_status: ExecutionStatus;
+  outcome: Outcome | null;
+  reply: string | null;
+  exchange_id: string | null;
+  runs: string[];
+  current_run_id: string | null;
+  clarification: string | null;
+  cleanup: string | null;
+  trace_id: string | null;
+  error: string | null;
+  requests_spent: number | null;
+};
+
+export type TimelineEvent = {
+  op_key: string;
+  run_id: string | null;
+  op_type: string | null;
+  event: string;
+  status: string | null;
+  result: Record<string, unknown> | null;
+  created_at: string;
+};
+
+export type AgentContinueIn = {
+  message?: string;
+  consent_size?: string | null;
+  order_id?: string | null;
+  order_item_id?: string | null;
+  size?: string | null;
+  qty?: number;
+};
+
+/** `POST /v1/agent/cases/{id}/continue`. `continued=false` for terminal cases. */
+export type AgentContinueOut = {
+  case_id: string;
+  run_id: string | null;
+  execution_status: ExecutionStatus;
+  continued: boolean;
+  outcome: Outcome | null;
+  reply: string | null;
+  exchange_id: string | null;
+};
+
+/** Row from `GET /v1/agent/cases`. */
+export type AgentCaseListItem = {
+  case_id: string;
+  message: string;
+  order_id: string | null;
+  order_item_id: string | null;
+  size: string | null;
+  qty: number;
+  execution_status: ExecutionStatus;
+  outcome: Outcome | null;
+  current_run_id: string | null;
+  runs: string[];
+  created_at: string;
+  updated_at: string;
+  reply: string | null;
+};
+
+/** Page from `GET /v1/agent/cases`. `total`/`summary` cover the full filter. */
+export type AgentCaseListOut = {
+  items: AgentCaseListItem[];
+  next_cursor: string | null;
+  total: number;
+  summary: {
+    execution_status: Record<string, number>;
+    outcome: Record<string, number>;
+  };
+};
+
+export type AgentCaseListQuery = {
+  execution?: ExecutionStatus | ExecutionStatus[];
+  outcome?: Outcome | Outcome[];
+  limit?: number;
+  cursor?: string | null;
+};
+
+/* -------------------------------------------------------------- endpoints */
+
+/** GET /v1/health — liveness probe. */
+export function getHealth(): Promise<HealthOut> {
+  return request<HealthOut>("/health");
+}
+
+/** GET /v1/ready — queue-derived readiness (depth, oldest queued age). */
+export function getReady(): Promise<ReadyOut> {
+  return request<ReadyOut>("/ready");
+}
+
+/** GET /v1/fixtures — synthetic orders/items and the return policy. */
+export function getFixtures(): Promise<FixturesOut> {
+  return request<FixturesOut>("/fixtures");
+}
+
+/** GET /v1/inventory — actual stock keyed by SKU and size (pure read). */
+export function getInventory(query: InventoryQuery = {}): Promise<InventoryOut> {
+  const params = new URLSearchParams();
+  if (query.sku) params.set("sku", query.sku);
+  if (query.size) params.set("size", query.size);
+  if (query.limit != null) params.set("limit", String(query.limit));
+  if (query.offset != null) params.set("offset", String(query.offset));
+  const qs = params.toString();
+  return request<InventoryOut>(`/inventory${qs ? `?${qs}` : ""}`);
+}
+
+/**
+ * POST /v1/agent/tickets — accept an agent ticket for asynchronous
+ * execution. Returns 202 with the new case id; poll `getAgentCase` for
+ * progress and outcome.
+ */
+export function submitAgentTicket(input: AgentTicketIn): Promise<AgentAccepted> {
+  return request<AgentAccepted>("/agent/tickets", {
+    method: "POST",
+    body: JSON.stringify(input),
+  });
+}
+
+/** GET /v1/agent/cases/{id} — execution status, outcome, and clarification. */
+export function getAgentCase(caseId: string): Promise<AgentStatusOut> {
+  return request<AgentStatusOut>(`/agent/cases/${encodeURIComponent(caseId)}`);
+}
+
+/**
+ * GET /v1/agent/cases — list durable agent-path cases, newest first.
+ * Read-only; filter by execution/outcome, paginate with `limit`/`cursor`.
+ */
+export function listAgentCases(query: AgentCaseListQuery = {}): Promise<AgentCaseListOut> {
+  const params = new URLSearchParams();
+  const append = (key: string, value: string | string[]) => {
+    for (const entry of Array.isArray(value) ? value : [value]) {
+      if (entry) params.append(key, entry);
+    }
+  };
+  if (query.execution) append("execution", query.execution);
+  if (query.outcome) append("outcome", query.outcome);
+  if (query.limit != null) params.set("limit", String(query.limit));
+  if (query.cursor) params.set("cursor", query.cursor);
+  const qs = params.toString();
+  return request<AgentCaseListOut>(`/agent/cases${qs ? `?${qs}` : ""}`);
+}
+
+/** GET /v1/agent/cases/{id}/timeline — sanitized events tagged with run ids. */
+export function getAgentCaseTimeline(caseId: string): Promise<TimelineEvent[]> {
+  return request<TimelineEvent[]>(`/agent/cases/${encodeURIComponent(caseId)}/timeline`);
+}
+
+/**
+ * POST /v1/agent/cases/{id}/continue — continue a case through the same
+ * agent path. Returns 202 when a fresh run was queued (`continued=true`);
+ * terminal cases echo their saved result with `continued=false`.
+ */
+export function continueAgentCase(
+  caseId: string,
+  input: AgentContinueIn,
+): Promise<AgentContinueOut> {
+  return request<AgentContinueOut>(`/agent/cases/${encodeURIComponent(caseId)}/continue`, {
+    method: "POST",
+    body: JSON.stringify(input),
+  });
+}

