+        return { status: "escalated", statusLabel: "Escalated to Human", actions: runs };
+      }
+      if (status.outcome === "clarification") {
+        return { status: "processing", statusLabel: "Clarification Required", actions: runs };
+      }
+      return { status: "resolved", statusLabel: "Resolved Autonomously", actions: runs };
+  }
+}
+
+export function isActiveExecution(status?: ExecutionStatus): boolean {
+  return status === "queued" || status === "running";
