import type { NextConfig } from "next";

const SWAPDESK_API_URL = (process.env.SWAPDESK_API_URL ?? "http://127.0.0.1:8000").replace(/\/$/, "");

const nextConfig: NextConfig = {
  /* config options here */
  experimental: {
    agentFeedback: true,
  },
  cacheComponents: true,
  partialPrefetching: true,
  async rewrites() {
    /* Proxy same-origin `/v1/*` calls to the SwapDesk FastAPI backend so the
       browser never hits a cross-origin request. Override the target with the
       SWAPDESK_API_URL environment variable. */
    return [{ source: "/v1/:path*", destination: `${SWAPDESK_API_URL}/v1/:path*` }];
  },
};

export default nextConfig;

/**
 * Typed client for the SwapDesk local mock API.
 *
 * The browser calls same-origin `/v1/...` paths; `next.config.ts` proxies
 * those to the FastAPI backend (default `http://127.0.0.1:8000`). Set
 * `NEXT_PUBLIC_SWAPDESK_API_URL` to call a remote origin directly instead
 * (that origin must then allow CORS).
 *
 * Only the agent contract in `docs/API_CONTRACT.md` is used here. The
 * legacy `/v1/tickets`, `/v1/cases/*`, and `/v1/demo/faults` routes are
 * deliberately excluded: agent tickets are accepted asynchronously (202)
 * and their progress is read by polling the status/timeline routes.
 */

const API_ORIGIN = (process.env.NEXT_PUBLIC_SWAPDESK_API_URL ?? "").replace(/\/$/, "");

export const API_BASE = `${API_ORIGIN}/v1`;

export class ApiError extends Error {
  status: number;
  detail: unknown;

  constructor(status: number, message: string, detail?: unknown) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.detail = detail;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${API_BASE}${path}`, {
      ...init,
      headers: {
        ...(init?.body ? { "Content-Type": "application/json" } : {}),
        ...init?.headers,
      },
      cache: "no-store",
    });
  } catch {
    throw new ApiError(0, "Cannot reach the SwapDesk API. Is the backend running?");
  }

  const text = await response.text();
  const payload = text ? safeJson(text) : null;

  if (!response.ok) {
    const detail =
      payload && typeof payload === "object" && "detail" in payload
        ? (payload as { detail: unknown }).detail
        : payload;
    const message =
      typeof detail === "string" ? detail : `Request failed with status ${response.status}`;
    throw new ApiError(response.status, message, payload);
  }

  return payload as T;
}

function safeJson(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

/* ------------------------------------------------------------------ types */

/** Business outcome once a run reaches a terminal state. */
export type Outcome = "arranged" | "clarification" | "denial" | "escalation";

/** Rolled-up execution state of a case across its runs. */
export type ExecutionStatus =
  | "queued"
  | "running"
  | "waiting_input"
  | "completed"
  | "failed";

export type HealthOut = {
  ok: boolean;
  service: string;
};

export type ReturnPolicy = {
  window_days: number;
  eligible_status: string;
  final_sale_excluded: boolean;
};

export type FixtureItem = {
  id: string;
  sku: string;
  size: string;
  qty: number;
  status: string;
  delivered_at: string | null;
  final_sale: boolean;
};

export type FixtureOrder = {
  id: string;
  customer_ref: string;
  items: FixtureItem[];
};

export type FixturesOut = {
  orders: FixtureOrder[];
  policy: ReturnPolicy;
};

export type AgentTicketIn = {
  message: string;
  order_id?: string | null;
  order_item_id?: string | null;
  size?: string | null;
  qty?: number;
  consent_size?: string | null;
  case_id?: string | null;
  idempotency_key?: string | null;
  resume?: boolean;
};

/** 202 accepted body from `POST /v1/agent/tickets`. */
export type AgentAccepted = {
  case_id: string;
  run_id: string;
  execution_status: ExecutionStatus;
  status_url: string;
  duplicate: boolean;
};

/** `GET /v1/agent/cases/{id}` — responsive, read-only case status. */
export type AgentStatusOut = {
  case_id: string;
  execution_status: ExecutionStatus;
  outcome: Outcome | null;
  reply: string | null;
  exchange_id: string | null;
  runs: string[];
  current_run_id: string | null;
  clarification: string | null;
  cleanup: string | null;
  trace_id: string | null;
  error: string | null;
  requests_spent: number | null;
};

export type TimelineEvent = {
  op_key: string;
  run_id: string | null;
  op_type: string | null;
  event: string;
  status: string | null;
  result: Record<string, unknown> | null;
  created_at: string;
};

export type AgentContinueIn = {
  message?: string;
  consent_size?: string | null;
  order_id?: string | null;
  order_item_id?: string | null;
  size?: string | null;
  qty?: number;
};

/** `POST /v1/agent/cases/{id}/continue`. `continued=false` for terminal cases. */
export type AgentContinueOut = {
  case_id: string;
  run_id: string | null;
  execution_status: ExecutionStatus;
  continued: boolean;
  outcome: Outcome | null;
  reply: string | null;
  exchange_id: string | null;
};

/* -------------------------------------------------------------- endpoints */

/** GET /v1/health — liveness probe. */
export function getHealth(): Promise<HealthOut> {
  return request<HealthOut>("/health");
}

/** GET /v1/fixtures — synthetic orders/items and the return policy. */
export function getFixtures(): Promise<FixturesOut> {
  return request<FixturesOut>("/fixtures");
}

/**
 * POST /v1/agent/tickets — accept an agent ticket for asynchronous
 * execution. Returns 202 with the new case id; poll `getAgentCase` for
 * progress and outcome.
 */
export function submitAgentTicket(input: AgentTicketIn): Promise<AgentAccepted> {
  return request<AgentAccepted>("/agent/tickets", {
    method: "POST",
    body: JSON.stringify(input),
  });
}

/** GET /v1/agent/cases/{id} — execution status, outcome, and clarification. */
export function getAgentCase(caseId: string): Promise<AgentStatusOut> {
  return request<AgentStatusOut>(`/agent/cases/${encodeURIComponent(caseId)}`);
}

/** GET /v1/agent/cases/{id}/timeline — sanitized events tagged with run ids. */
export function getAgentCaseTimeline(caseId: string): Promise<TimelineEvent[]> {
  return request<TimelineEvent[]>(`/agent/cases/${encodeURIComponent(caseId)}/timeline`);
}

/**
 * POST /v1/agent/cases/{id}/continue — continue a case through the same
 * agent path. Returns 202 when a fresh run was queued (`continued=true`);
 * terminal cases echo their saved result with `continued=false`.
 */
export function continueAgentCase(
  caseId: string,
  input: AgentContinueIn,
): Promise<AgentContinueOut> {
  return request<AgentContinueOut>(`/agent/cases/${encodeURIComponent(caseId)}/continue`, {
    method: "POST",
    body: JSON.stringify(input),
  });
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import {
  continueAgentCase as apiContinueAgentCase,
  getAgentCase as apiGetAgentCase,
  getAgentCaseTimeline as apiGetAgentCaseTimeline,
  getFixtures as apiGetFixtures,
  getHealth as apiGetHealth,
  submitAgentTicket as apiSubmitAgentTicket,
  type AgentContinueIn,
  type AgentContinueOut,
  type AgentStatusOut,
  type AgentTicketIn,
  type ExecutionStatus,
  type FixturesOut,
  type Outcome,
  type TimelineEvent,
} from "@/lib/api";

export type TicketStatus = "resolved" | "escalated" | "processing";

export type Ticket = {
  id: string;
  message: string;
  status: TicketStatus;
  statusLabel: string;
  actions: string[];
  time: string;
  sku: string;
  /** Set for cases created through the backend API. */
  outcome?: Outcome;
  reply?: string;
  exchangeId?: string | null;
  runId?: string;
  live?: boolean;
  /** Raw agent execution state, when the case came from the API. */
  executionStatus?: ExecutionStatus;
  clarification?: string | null;
  error?: string | null;
  traceId?: string | null;
  requestsSpent?: number | null;
  cleanup?: string | null;
  duplicate?: boolean;
};

export type InventoryItem = {
  sku: string;
  name: string;
  size: number;
  stock: number;
  res: number;
  wh: string;
};

export type ApiHealth = "unknown" | "online" | "offline";

const POLL_MS = 1500;

export const MOCK_TICKET = {
  message: "Jordan 4 size 43 exchange",
  status: "resolved" as TicketStatus,
  statusLabel: "Resolved Autonomously",
  actions: ["RESERVE_STOCK", "CREATE_LABEL"],
  time: "Just now",
  sku: "AJ4-MIL-43",
};

const createInitialTickets = (): Ticket[] => [
  {
    id: "TCK-9042",
    message: "Jordan 4s are too tight, need size 43.",
    status: "resolved",
    statusLabel: "Resolved Autonomously",
    actions: ["RESERVE_STOCK", "CREATE_LABEL"],
    time: "Just now",
    sku: "AJ4-MIL-43",
  },
  {
    id: "TCK-9043",
    message: "I want a refund but I bought these 90 days ago.",
    status: "escalated",
    statusLabel: "Escalated to Human",
    actions: ["POLICY_DENY"],
    time: "2 min ago",
    sku: "SMB-OG-41",
  },
  {
    id: "TCK-9044",
    message: "Need a size 10 exchange.",
    status: "resolved",
    statusLabel: "Resolved (Recovered)",
    actions: ["API_TIMEOUT_RECOVERED"],
    time: "5 min ago",
    sku: "GK30-BLK-44",
  },
];

const createInitialInventory = (): InventoryItem[] => [
  { sku: "AJ4-MIL-43", name: "Air Jordan 4 Military", size: 43, stock: 5, res: 1, wh: "WH-AMS-02" },
  { sku: "AJ4-MIL-42", name: "Air Jordan 4 Military", size: 42, stock: 3, res: 0, wh: "WH-AMS-02" },
  { sku: "SMB-OG-41", name: "Adidas Samba OG", size: 41, stock: 12, res: 2, wh: "WH-BER-01" },
  { sku: "NB550-GRY-39", name: "New Balance 550 Grey", size: 39, stock: 0, res: 0, wh: "WH-BER-01" },
  { sku: "GK30-BLK-44", name: "Asics Gel-Kayano 30", size: 44, stock: 5, res: 1, wh: "WH-AMS-02" },
];

const LIVE_CASES_KEY = "swapdesk.liveCases.v1";

function statusView(status: AgentStatusOut): {
  status: TicketStatus;
  statusLabel: string;
  actions: string[];
} {
  const runs = status.runs.length > 0 ? status.runs.map((run) => run.toUpperCase()) : ["INTAKE"];
  switch (status.execution_status) {
    case "queued":
      return { status: "processing", statusLabel: "Queued", actions: runs };
    case "running":
      return { status: "processing", statusLabel: "Agent Processing", actions: runs };
    case "waiting_input":
      return { status: "processing", statusLabel: "Clarification Required", actions: runs };
    case "failed":
      return { status: "escalated", statusLabel: "Run Failed", actions: runs };
    case "completed":
    default:
      if (status.outcome === "denial") {
        return { status: "escalated", statusLabel: "Policy Denied", actions: runs };
      }
      if (status.outcome === "escalation") {
        return { status: "escalated", statusLabel: "Escalated to Human", actions: runs };
      }
      if (status.outcome === "clarification") {
        return { status: "processing", statusLabel: "Clarification Required", actions: runs };
      }
      return { status: "resolved", statusLabel: "Resolved Autonomously", actions: runs };
  }
}

export function isActiveExecution(status?: ExecutionStatus): boolean {
  return status === "queued" || status === "running";
}

function readLiveCases(): Ticket[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(LIVE_CASES_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as Ticket[]) : [];
  } catch {
    return [];
  }
}

function writeLiveCases(tickets: Ticket[]) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(
      LIVE_CASES_KEY,
      JSON.stringify(tickets.filter((ticket) => ticket.live)),
    );
  } catch {
    /* storage unavailable — non-fatal */
  }
}

type SwapDeskContextValue = {
  tickets: Ticket[];
  inventory: InventoryItem[];
  fixtures: FixturesOut | null;
  health: ApiHealth;
  apiError: string | null;
  caseStatus: Record<string, AgentStatusOut>;
  refreshHealth: () => Promise<boolean>;
  loadFixtures: () => Promise<FixturesOut | null>;
  /** POST /v1/agent/tickets — 202 accepted; progress streams via polling. */
  submitAgentTicket: (input: AgentTicketIn) => Promise<Ticket>;
  /** GET /v1/agent/cases/{id} — one status read; starts polling if active. */
  loadCase: (id: string) => Promise<AgentStatusOut | null>;
  getTimeline: (id: string) => Promise<TimelineEvent[]>;
  continueCase: (id: string, input: AgentContinueIn) => Promise<AgentContinueOut>;
  /* Local demo helpers (offline fallback). */
  simulateTicket: () => Ticket;
  submitCustomerTicket: (message: string) => Ticket;
  resetMockData: () => void;
  getTicket: (id: string) => Ticket | undefined;
};

const SwapDeskContext = createContext<SwapDeskContextValue | null>(null);

export function SwapDeskProvider({ children }: { children: ReactNode }) {
  const [tickets, setTickets] = useState<Ticket[]>(createInitialTickets);
  const [inventory, setInventory] = useState<InventoryItem[]>(createInitialInventory);
  const [fixtures, setFixtures] = useState<FixturesOut | null>(null);
  const [health, setHealth] = useState<ApiHealth>("unknown");
  const [apiError, setApiError] = useState<string | null>(null);
  const [caseStatus, setCaseStatus] = useState<Record<string, AgentStatusOut>>({});
  const seq = useRef(9045);
  const pollers = useRef(new Map<string, number>());

  /* Rehydrate cases created through the API after mount (avoids SSR drift). */
  useEffect(() => {
    const live = readLiveCases();
    if (live.length === 0) return;
    const timer = window.setTimeout(() => {
      setTickets((prev) => [...live, ...prev.filter((ticket) => !ticket.live)]);
    }, 0);
    return () => window.clearTimeout(timer);
  }, []);

  useEffect(() => {
    writeLiveCases(tickets);
  }, [tickets]);

  /* Stop every background poll when the provider unmounts. */
  useEffect(() => {
    const timers = pollers.current;
    return () => {
      timers.forEach((timer) => window.clearTimeout(timer));
      timers.clear();
    };
  }, []);

  const rememberTicket = useCallback((ticket: Ticket) => {
    setTickets((prev) => [ticket, ...prev.filter((existing) => existing.id !== ticket.id)]);
  }, []);

  const applyStatus = useCallback((id: string, status: AgentStatusOut) => {
    setCaseStatus((prev) => ({ ...prev, [id]: status }));
    const view = statusView(status);
    setTickets((prev) =>
      prev.map((ticket) =>
        ticket.id === id
          ? {
              ...ticket,
              status: view.status,
              statusLabel: view.statusLabel,
              actions: view.actions,
              outcome: status.outcome ?? undefined,
              reply: status.reply ?? undefined,
              exchangeId: status.exchange_id,
              executionStatus: status.execution_status,
              clarification: status.clarification,
              error: status.error,
              traceId: status.trace_id,
              requestsSpent: status.requests_spent,
              cleanup: status.cleanup,
              runId: status.current_run_id ?? ticket.runId,
            }
          : ticket,
      ),
    );
  }, []);

  /* Poll a case until it reaches a terminal state or needs input. The
   * worker (python -m swapdesk.worker) advances queued runs. */
  const watchCase = useCallback(
    (id: string) => {
      if (pollers.current.has(id)) return;
      const poll = async () => {
        try {
          const status = await apiGetAgentCase(id);
          applyStatus(id, status);
          if (isActiveExecution(status.execution_status)) {
            pollers.current.set(id, window.setTimeout(poll, POLL_MS));
          } else {
            pollers.current.delete(id);
          }
        } catch {
          pollers.current.delete(id);
        }
      };
      pollers.current.set(id, window.setTimeout(poll, 0));
    },
    [applyStatus],
  );

  const refreshHealth = useCallback(async () => {
    try {
      const result = await apiGetHealth();
      const online = result.ok === true;
      setHealth(online ? "online" : "offline");
      if (online) setApiError(null);
      return online;
    } catch (error) {
      setHealth("offline");
      setApiError(error instanceof Error ? error.message : "Health check failed");
      return false;
    }
  }, []);

  const loadFixtures = useCallback(async () => {
    try {
      const result = await apiGetFixtures();
      setFixtures(result);
      setApiError(null);
      return result;
    } catch (error) {
      setApiError(error instanceof Error ? error.message : "Could not load fixtures");
      return null;
    }
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      void refreshHealth();
      void loadFixtures();
    }, 0);
    return () => window.clearTimeout(timer);
  }, [refreshHealth, loadFixtures]);

  const submitAgentTicket = useCallback(
    async (input: AgentTicketIn) => {
      const accepted = await apiSubmitAgentTicket(input);
      const ticket: Ticket = {
        id: accepted.case_id,
        message: input.message,
        status: "processing",
        statusLabel: accepted.execution_status === "queued" ? "Queued" : "Agent Processing",
        actions: ["INTAKE", accepted.run_id.toUpperCase()],
        time: "Just now",
        sku: input.order_item_id ?? "—",
        live: true,
        executionStatus: accepted.execution_status,
        runId: accepted.run_id,
        duplicate: accepted.duplicate,
      };
      rememberTicket(ticket);
      setHealth("online");
      setApiError(null);
      watchCase(accepted.case_id);
      return ticket;
    },
    [rememberTicket, watchCase],
  );

  const loadCase = useCallback(
    async (id: string) => {
      try {
        const status = await apiGetAgentCase(id);
        applyStatus(id, status);
        if (isActiveExecution(status.execution_status)) watchCase(id);
        return status;
      } catch {
        return null;
      }
    },
    [applyStatus, watchCase],
  );

  const getTimeline = useCallback(async (id: string) => {
    try {
      return await apiGetAgentCaseTimeline(id);
    } catch {
      return [];
    }
  }, []);

  const continueCase = useCallback(
    async (id: string, input: AgentContinueIn) => {
      const result = await apiContinueAgentCase(id, input);
      setApiError(null);
      if (result.continued) {
        setTickets((prev) =>
          prev.map((ticket) =>
            ticket.id === id
              ? {
                  ...ticket,
                  status: "processing",
                  statusLabel: "Queued",
                  executionStatus: "queued",
                  outcome: undefined,
                  reply: undefined,
                  clarification: null,
                  error: null,
                  runId: result.run_id ?? ticket.runId,
                }
              : ticket,
          ),
        );
        watchCase(id);
      } else {
        await loadCase(id);
      }
      return result;
    },
    [loadCase, watchCase],
  );

  const simulateTicket = useCallback(() => {
    const ticket: Ticket = { id: `TCK-${seq.current++}`, ...MOCK_TICKET };
    setTickets((prev) => [ticket, ...prev]);
    setInventory((prev) =>
      prev.map((item) =>
        item.sku === MOCK_TICKET.sku
          ? { ...item, stock: Math.max(0, item.stock - 1), res: item.res + 1 }
          : item,
      ),
    );
    return ticket;
  }, []);

  const submitCustomerTicket = useCallback((message: string) => {
    const text = message.trim() || "My Jordan 4s arrived but are too tight. I need to exchange for a size 43.";
    const ticket: Ticket = {
      id: `TCK-${seq.current++}`,
      message: text,
      status: "processing",
      statusLabel: "Agent Processing",
      actions: ["INTAKE", "ROUTING"],
      time: "Just now",
      sku: "AJ4-MIL-43",
    };
    setTickets((prev) => [ticket, ...prev]);
    return ticket;
  }, []);

  const resetMockData = useCallback(() => {
    setTickets(createInitialTickets());
    setInventory(createInitialInventory());
    setApiError(null);
  }, []);

  const getTicket = useCallback((id: string) => tickets.find((ticket) => ticket.id === id), [tickets]);

  const value = useMemo(
    () => ({
      tickets,
      inventory,
      fixtures,
      health,
      apiError,
      caseStatus,
      refreshHealth,
      loadFixtures,
      submitAgentTicket,
      loadCase,
      getTimeline,
      continueCase,
      simulateTicket,
      submitCustomerTicket,
      resetMockData,
      getTicket,
    }),
    [
      tickets,
      inventory,
      fixtures,
      health,
      apiError,
      caseStatus,
      refreshHealth,
      loadFixtures,
      submitAgentTicket,
      loadCase,
      getTimeline,
      continueCase,
      simulateTicket,
      submitCustomerTicket,
      resetMockData,
      getTicket,
    ],
  );

  return <SwapDeskContext.Provider value={value}>{children}</SwapDeskContext.Provider>;
}

export function useSwapDesk() {
  const context = useContext(SwapDeskContext);
  if (!context) {
    throw new Error("useSwapDesk must be used within a SwapDeskProvider");
  }
  return context;
}

