"use client";

import { useState } from "react";
import { RefreshCw, RotateCcw } from "lucide-react";
import { AppShell, PageTitle } from "@/components/AppShell";
import { useSwapDesk } from "@/store/swapdesk";
import type { FixtureItem, ReturnPolicy } from "@/lib/api";

function isEligible(item: FixtureItem, policy: ReturnPolicy): boolean {
  if (policy.final_sale_excluded && item.final_sale) return false;
  if (item.status !== policy.eligible_status) return false;
  if (!item.delivered_at) return false;
  const days = (Date.now() - Date.parse(item.delivered_at)) / 86_400_000;
  return days <= policy.window_days;
}

export default function InventoryPage() {
  const { inventory, fixtures, loadFixtures, resetMockData } = useSwapDesk();
  const [refreshing, setRefreshing] = useState(false);

  const refresh = async () => {
    setRefreshing(true);
    await loadFixtures();
    setRefreshing(false);
  };

  return (
    <AppShell crumbs={[{ label: "SwapDesk", to: "/" }, { label: "Inventory" }]}>
      <PageTitle
        title="Inventory"
        sub="Live fixture catalogue and return policy served by the SwapDesk API."
        right={
          <div className="flex shrink-0 items-center gap-2">
            <button
              type="button"
              onClick={refresh}
              disabled={refreshing}
              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-xs font-medium text-foreground transition-colors hover:bg-accent/60 disabled:opacity-60"
              title="Reload fixtures from GET /v1/fixtures"
            >
              <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? "animate-spin" : ""}`} />
              Refresh
            </button>
            <button
              type="button"
              onClick={resetMockData}
              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-xs font-medium text-foreground transition-colors hover:bg-accent/60"
              title="Clear the ticket queue and restore local demo defaults"
            >
              <RotateCcw className="h-3.5 w-3.5" />
              Reset Mock Data
            </button>
          </div>
        }
      />

      {fixtures ? (
        <>
          <div className="panel mb-4 flex flex-wrap items-center gap-x-6 gap-y-2 p-4 text-xs text-muted-foreground">
            <span className="font-mono uppercase tracking-[0.18em] text-muted-foreground/80">Return policy</span>
            <span>
              Window <span className="num text-foreground">{fixtures.policy.window_days}d</span>
            </span>
            <span>
              Eligible status <span className="font-mono text-foreground">{fixtures.policy.eligible_status}</span>
            </span>
            <span>
              Final sale excluded{" "}
              <span className="font-mono text-foreground">{fixtures.policy.final_sale_excluded ? "yes" : "no"}</span>
            </span>
          </div>

          <div className="panel overflow-x-auto">
            <table className="w-full min-w-[720px] text-sm">
              <thead className="text-left text-xs text-muted-foreground">
                <tr className="border-b border-hairline">
                  {["Item", "SKU", "Size", "Order", "Status", "Delivered", "Final Sale", "Eligible"].map((h) => (
                    <th key={h} className="px-5 py-3 font-medium">
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-hairline">
                {fixtures.orders.flatMap((order) =>
                  order.items.map((item) => {
                    const eligible = isEligible(item, fixtures.policy);
                    return (
                      <tr key={item.id} className="hover:bg-accent/30">
                        <td className="px-5 py-3 font-mono text-xs">{item.id}</td>
                        <td className="px-5 py-3 font-mono text-xs">{item.sku}</td>
                        <td className="num px-5 py-3">{item.size}</td>
                        <td className="px-5 py-3 font-mono text-xs text-muted-foreground">{order.id}</td>
                        <td className="px-5 py-3">{item.status}</td>
                        <td className="px-5 py-3 text-muted-foreground">{item.delivered_at ?? "—"}</td>
                        <td className="px-5 py-3">
                          {item.final_sale ? <span className="text-warning">Yes</span> : <span className="text-muted-foreground">No</span>}
                        </td>
                        <td className="px-5 py-3">
                          <span className={eligible ? "font-medium text-success" : "text-danger"}>
                            {eligible ? "Eligible" : "Ineligible"}
                          </span>
                        </td>
                      </tr>
                    );
                  }),
                )}
              </tbody>
            </table>
          </div>
        </>
      ) : (
        <div className="panel overflow-x-auto">
          <div className="border-b border-hairline px-5 py-3 text-xs text-muted-foreground">
            Backend offline — showing local demo stock.
          </div>
          <table className="w-full min-w-[640px] text-sm">
            <thead className="text-left text-xs text-muted-foreground">
              <tr className="border-b border-hairline">
                {["SKU", "Product", "Size", "Available", "Reserved", "Warehouse"].map((h) => (
                  <th key={h} className="px-5 py-3 font-medium">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-hairline">
              {inventory.map((i) => (
                <tr key={i.sku} className="hover:bg-accent/30">
                  <td className="px-5 py-3 font-mono text-xs">{i.sku}</td>
                  <td className="px-5 py-3">{i.name}</td>
                  <td className="num px-5 py-3">{i.size}</td>
                  <td className={`num px-5 py-3 ${i.stock === 0 ? "text-danger" : ""}`}>{i.stock}</td>
                  <td className={`num px-5 py-3 ${i.res ? "text-success" : "text-muted-foreground"}`}>{i.res}</td>
                  <td className="px-5 py-3 font-mono text-xs text-muted-foreground">{i.wh}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </AppShell>
  );
}

