Function:
```
export function listAgentCases(query: AgentCaseListQuery = {}): Promise<AgentCaseListOut> {
  const params = new URLSearchParams();
  const push = (key, value) => { for (const v of Array.isArray(value) ? value : [value]) if (v != null) params.append(key, v); };
  if (query.execution) push("execution", query.execution);
  if (query.outcome) push("outcome", query.outcome);
  if (query.limit != null) params.set("limit", String(query.limit));
  if (query.cursor) params.set("cursor", query.cursor);
  const qs = params.toString();
