/** GET /v1/agent/cases/{id} — execution status, outcome, and clarification. */
export function getAgentCase(caseId: string): Promise<AgentStatusOut> {
  return request<AgentStatusOut>(`/agent/cases/${encodeURIComponent(caseId)}`);
}

/**
 * GET /v1/agent/cases — list durable agent-path cases, newest first.
 * Read-only; filter by execution/outcome, paginate with `limit`/`cursor`.
 */
export function listAgentCases(query: AgentCaseListQuery = {}): Promise<AgentCaseListOut> {
  const params = new URLSearchParams();
  const append = (key: string, value: string | string[]) => {
    for (const entry of Array.isArray(value) ? value : [value]) {
      if (entry) params.append(key, entry);
    }
  };
  if (query.execution) append("execution", query.execution);
  if (query.outcome) append("outcome", query.outcome);
  if (query.limit != null) params.set("limit", String(query.limit));
  if (query.cursor) params.set("cursor", query.cursor);
  const qs = params.toString();
  return request<AgentCaseListOut>(`/agent/cases${qs ? `?${qs}` : ""}`);
}

