const refreshReady = useCallback(async () => {
  try {
    const result = await apiGetReady();
    setReady(result);
    return result;
  } catch {
    setReady(null);
    return null;
  }
}, []);

const refreshCases = useCallback(async () => {
  try {
    const result = await apiListAgentCases({ limit: 25 });
    setApiError(null);
    if (result.items.length > 0) {
      setTickets((prev) => {
        const incoming = result.items.map(ticketFromCase);
        const seen = new Set(incoming.map((ticket) => ticket.id));
        return [...incoming, ...prev.filter((ticket) => !seen.has(ticket.id))];
      });
    }
    for (const item of result.items) {
      if (isActiveExecution(item.execution_status)) watchCase(item.case_id);
    }
    return result;
  } catch {
    return null;
  }
}, [watchCase]);

useEffect(() => {
  const timer = window.setTimeout(() => {
    void refreshHealth();
    void refreshReady();
    void refreshCases();
    void loadFixtures();
  }, 0);
  return () => window.clearTimeout(timer);
}, [refreshHealth, refreshReady, refreshCases, loadFixtures]);

