  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-danger: var(--danger);
  --color-hairline: var(--hairline);
  --color-glass: var(--glass);
}

:root {
  --radius: 0.75rem;
  --background: #0a0a0b;
  --foreground: #f2f2f3;
  --card: #111113;
  --card-foreground: #f2f2f3;
  --popover: #151517;
  --popover-foreground: #f2f2f3;
  --primary: oklch(0.84 0.2 152);
  --primary-foreground: oklch(0.16 0.03 152);
  --secondary: oklch(0.22 0.005 286);
  --secondary-foreground: oklch(0.92 0.003 286);
  --muted: oklch(0.21 0.005 286);
  --muted-foreground: oklch(0.65 0.01 286);
  --accent: oklch(0.24 0.006 286);
  --accent-foreground: oklch(0.96 0.003 286);
  --destructive: oklch(0.63 0.22 20);
  --destructive-foreground: oklch(0.98 0 0);
  --border: #222225;
  --input: #222225;
  --ring: oklch(0.84 0.2 152 / 50%);
  --success: oklch(0.84 0.2 152);
  --warning: oklch(0.8 0.16 75);
  --danger: oklch(0.63 0.22 20);
  --hairline: oklch(1 0 0 / 8%);
  --glass: oklch(0.2 0.005 286 / 55%);
  --glow-success: 0 0 0 1px oklch(0.84 0.2 152 / 35%), 0 8px 40px -8px oklch(0.84 0.2 152 / 55%);
  --glow-warning: 0 0 24px -6px oklch(0.8 0.16 75 / 50%);
  --gradient-ambient:
    radial-gradient(60rem 30rem at 85% -10%, oklch(0.84 0.2 152 / 9%), transparent 60%),
    radial-gradient(40rem 25rem at -10% 110%, oklch(0.8 0.16 75 / 6%), transparent 60%);
}

@layer base {
  * {
    border-color: var(--color-border);
  }
  html {
    font-size: clamp(14px, calc(14px + 0.125vw), 16px);
  }
  html,
  body {
    overflow-x: hidden;
  }
  body {
    background-color: var(--color-background);
    background-image: var(--gradient-ambient);
    background-attachment: fixed;
    color: var(--color-foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
  }
  h1,
  h2,
  h3,
  h4 {
    font-family: var(--font-display);
    letter-spacing: -0.02em;
  }
}

@utility glass {
  background: var(--glass);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
  border: 1px solid var(--hairline);
}

@utility panel {
  background: linear-gradient(180deg, oklch(0.19 0.004 286 / 90%), oklch(0.17 0.004 286 / 90%));
  border: 1px solid var(--hairline);
  border-radius: var(--radius-2xl);
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 4%),
    0 20px 50px -30px oklch(0 0 0 / 80%);
}

@utility glow-success {
  box-shadow: var(--glow-success);
}
@utility glow-warning {
  box-shadow: var(--glow-warning);
}

@utility num {
  font-family: var(--font-display);
  font-variant-numeric: tabular-nums;
}

@keyframes pulse-dot {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.8);
  }
}
@utility pulse-dot {
  animation: pulse-dot 1.8s ease-in-out infinite;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@utility rise {
  animation: rise 0.5s ease-out both;
}

