import type { Metadata, Viewport } from "next";
import { Bricolage_Grotesque, Geist_Mono, Plus_Jakarta_Sans } from "next/font/google";
import { Toaster } from "sonner";
import { SwapDeskProvider } from "@/store/swapdesk";
import {
  SITE_DESCRIPTION,
  SITE_KEYWORDS,
  SITE_NAME,
  SITE_TITLE,
  SITE_URL,
} from "@/lib/seo";
import "./globals.css";

const jakartaSans = Plus_Jakarta_Sans({
  variable: "--font-jakarta",
  subsets: ["latin"],
});

const bricolage = Bricolage_Grotesque({
  variable: "--font-bricolage",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title: {
    default: SITE_TITLE,
    template: `%s · ${SITE_NAME}`,
  },
  description: SITE_DESCRIPTION,
  applicationName: SITE_NAME,
  keywords: SITE_KEYWORDS,
  authors: [{ name: "SwapDesk Team" }],
  creator: SITE_NAME,
  publisher: SITE_NAME,
  category: "technology",
  alternates: {
    canonical: "/",
  },
  openGraph: {
    type: "website",
    siteName: SITE_NAME,
    title: SITE_TITLE,
    description: SITE_DESCRIPTION,
    url: "/",
    locale: "en_US",
  },
  twitter: {
    card: "summary_large_image",
    title: SITE_TITLE,
    description: SITE_DESCRIPTION,
  },
  robots: {
    index: true,
    follow: true,
    googleBot: {
      index: true,
      follow: true,
      "max-image-preview": "large",
      "max-snippet": -1,
      "max-video-preview": -1,
    },
  },
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  colorScheme: "dark",
  themeColor: "#0a0a0b",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${jakartaSans.variable} ${bricolage.variable} ${geistMono.variable} h-full antialiased`}>
      <body className="min-h-full flex flex-col">
        <SwapDeskProvider>
          {children}
          <Toaster theme="dark" position="bottom-right" richColors />
        </SwapDeskProvider>
      </body>
    </html>
  );
}

parts.text:
Only a handful. Good — manageable.

Plan:
1. Implement a theme system:
   - Introduce a `surface` token for subtle overlays (replacing `bg-white/[0.025]`, `bg-white/[0.04]`, `bg-white/[0.06]`), theme-aware.
   - Add light theme overrides in globals.css under `html.light`.
   - Make `panel` utility use variables so it adapts (or add light override).
   - Make mobile nav bg use a variable.
   - Update `@custom-variant dark` usage? Components don't seem to use `dark:` variants. Let me check. Probably not.

2. Add `ThemeToggle` component (client) with sun/moon icons from lucide, toggling `document.documentElement.classList` and localStorage, plus a small inline script in layout to avoid flash.

3. Place the toggle in the sidebar (AppShell), near BackendStatus/collapse button.

Let me decide theme model: default = dark (current). Add class `light` to html for light mode. Persist preference. Add a pre-hydration script reading localStorage and applying class to avoid flash.

Actually, cleaner: default follow the OS? The user just wants a toggle. I'll default to dark (matches current brand), toggle to light, persist in localStorage key "swapdesk-theme".

Now, the toggling: since server renders without a class, and client applies on mount, there will be a flash. To avoid, inject a blocking script in `<head>` via `<script dangerouslySetInnerHTML>` in layout. That's standard.

Let me design the light palette. Current dark uses near-black backgrounds. Light palette:
```
html.light {
  --background: #f6f7f8;   /* or oklch light */
  --foreground: #15161a;
  --card: #ffffff;
  --card-foreground: #15161a;
