  --popover-foreground: #15161a;
  --primary: oklch(0.62 0.19 152);   /* darker green for contrast on light */
  --primary-foreground: #ffffff;
  --secondary: oklch(0.94 0.005 286);
  --secondary-foreground: oklch(0.25 0.005 286);
  --muted: oklch(0.95 0.004 286);
  --muted-foreground: oklch(0.45 0.01 286);
  --accent: oklch(0.93 0.006 286);
  --accent-foreground: oklch(0.22 0.005 286);
